{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Golidocitinib, the closest analogue (Morgan 0.346), shares the aminopyrimidine-aniline core and had >80% oral bioavailability in healthy humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "CC-292, a covalent BTK inhibitor with the same acrylamide-aniline and aminopyrimidine motif, showed excellent oral bioavailability in a human Phase IA study, directly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Imatinib, sharing the aminopyrimidine and basic amine/aniline features, has an absolute bioavailability of 98.3% in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Brexpiprazole, sharing the N-methylindazole heteroaryl substructure, has 95% absolute bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Zongertinib, an acrylamide-containing kinase inhibitor with an aminopyrimidine motif, was predicted to have 41% oral bioavailability in humans, still above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Nilotinib, a lower-similarity analogue sharing the aminopyrimidine-aniline scaffold, has only ~30% oral bioavailability in humans; this is contradictory but less transferable because it lacks the acrylamide and basic diamine side chain.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High-F evidence from closer analogues (golidocitinib, CC-292, imatinib, brexpiprazole, zongertinib) outweighs lower-similarity low-F nilotinib; the query's acrylamide-aminopyrimidine-basic amine features align with high oral bioavailability. Predicted high (F >= 20%).",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "All evidence comes from analogues with modest Morgan similarity (0.24-0.35).",
    "Human PK for the exact covalent BTK inhibitor scaffold is not directly available.",
    "Low-F nilotinib/flumatinib evidence suggests possible solubility or efflux liabilities that are not fully excluded."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

